CREATE OR REPLACE FUNCTION public.lifecycle_reference_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      DECLARE payload JSONB; old_payload JSONB; p UUID; t UUID;
      BEGIN
        IF TG_OP='DELETE' THEN payload=to_jsonb(OLD); ELSE payload=to_jsonb(NEW); END IF;
        IF TG_OP='UPDATE' THEN
          old_payload=to_jsonb(OLD);
          IF ROW(payload->>'product_id',payload->>'tenant_id') IS DISTINCT FROM
             ROW(old_payload->>'product_id',old_payload->>'tenant_id') THEN
            RAISE EXCEPTION 'Reference scope cannot be reassigned';
          END IF;
        END IF;
        -- Lifecycle receipts document retention decisions, not consuming business references.
        IF TG_TABLE_NAME='action_receipts' AND payload->>'operation' LIKE 'evidence.lifecycle.%' THEN
          IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
        END IF;
        p=(payload->>'product_id')::uuid; t=(payload->>'tenant_id')::uuid;
        PERFORM 1 FROM products WHERE id=p AND tenant_id=t FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Reference product gate unavailable'; END IF;
        IF TG_OP<>'DELETE' AND EXISTS (
          SELECT 1 FROM lifecycle_objects o WHERE o.product_id=p AND o.tenant_id=t
          AND ((o.state->'value'->>'pending_intent_id') IS NOT NULL
               OR o.state->'value'->>'disposition' IN ('quarantined','unknown','purged'))
          AND position(o.id::text in payload::text)>0
        ) THEN RAISE EXCEPTION 'Pending or isolated original prohibits new references'; END IF;
        UPDATE products SET lifecycle_epoch=lifecycle_epoch+1 WHERE id=p AND tenant_id=t;
        IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
      END $function$

CREATE OR REPLACE FUNCTION public.protect_lifecycle_record()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      BEGIN
        IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Lifecycle history is retained'; END IF;
        IF ROW(NEW.id,NEW.tenant_id,NEW.product_id,NEW.created_at) IS DISTINCT FROM
           ROW(OLD.id,OLD.tenant_id,OLD.product_id,OLD.created_at)
           OR NEW.revision<>OLD.revision+1 THEN
          RAISE EXCEPTION 'Lifecycle identity and monotonic revision required';
        END IF;
        IF TG_TABLE_NAME='lifecycle_objects' THEN
          IF ROW(NEW.owner_id,NEW.reference) IS DISTINCT FROM ROW(OLD.owner_id,OLD.reference) THEN
            RAISE EXCEPTION 'Exact original binding cannot change'; END IF;
          IF ROW(NEW.manual_hold,NEW.retention_until) IS DISTINCT FROM ROW(OLD.manual_hold,OLD.retention_until)
             AND NEW.protection_revision<>OLD.protection_revision+1 THEN
            RAISE EXCEPTION 'Retention protection must advance'; END IF;
          IF NEW.protection_revision<OLD.protection_revision OR
             NEW.protection_revision>OLD.protection_revision+1 THEN
            RAISE EXCEPTION 'Invalid protection revision'; END IF;
        ELSIF TG_TABLE_NAME='upload_attempts' THEN
          IF ROW(NEW.owner_id,NEW.reference,NEW.request_key,NEW.request_digest,NEW.title,NEW.filename)
             IS DISTINCT FROM ROW(OLD.owner_id,OLD.reference,OLD.request_key,OLD.request_digest,OLD.title,OLD.filename)
             OR OLD.status<>'reserved' OR NEW.status NOT IN ('committed','abandoned') THEN
            RAISE EXCEPTION 'Upload terminal evidence cannot be reversed'; END IF;
          IF NEW.status='abandoned' AND EXISTS(SELECT 1 FROM uploaded_originals
                 WHERE id=NEW.id AND tenant_id=NEW.tenant_id) THEN
            RAISE EXCEPTION 'Registered original cannot be abandoned'; END IF;
        ELSIF TG_TABLE_NAME='lifecycle_intents' THEN
          IF ROW(NEW.object_id,NEW.actor_id,NEW.intent_digest,NEW.reason) IS DISTINCT FROM
             ROW(OLD.object_id,OLD.actor_id,OLD.intent_digest,OLD.reason) THEN
            RAISE EXCEPTION 'Named decision binding cannot change'; END IF;
        END IF;
        RETURN NEW;
      END $function$

CREATE OR REPLACE FUNCTION public.protect_professional_pointer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      DECLARE target professional_authority_facts%ROWTYPE;
      BEGIN
        IF TG_OP='DELETE' THEN
          RAISE EXCEPTION 'Professional authority history is retained';
        END IF;
        SELECT * INTO target FROM professional_authority_facts WHERE id=NEW.fact_id
          AND tenant_id=NEW.tenant_id AND product_id=NEW.product_id;
        IF NOT FOUND OR ROW(NEW.project_id,NEW.subject_id,NEW.kind,NEW.series_id,
            NEW.issuer_key,NEW.external_id,NEW.fact_revision)
          IS DISTINCT FROM ROW(target.project_id,target.subject_id,target.kind,
            target.series_id,target.issuer_key,target.external_id,target.revision) THEN
          RAISE EXCEPTION 'Authority pointer must bind its exact fact';
        END IF;
        IF TG_OP='INSERT' THEN
          IF NEW.epoch<>1 OR NEW.fact_revision<>1 OR target.previous_id IS NOT NULL THEN
            RAISE EXCEPTION 'Authority pointer must begin at the first version';
          END IF;
        ELSIF ROW(NEW.id,NEW.tenant_id,NEW.product_id,NEW.project_id,NEW.subject_id,
            NEW.kind,NEW.issuer_key,NEW.external_id,NEW.series_id,NEW.created_at)
          IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.product_id,OLD.project_id,
            OLD.subject_id,OLD.kind,OLD.issuer_key,OLD.external_id,OLD.series_id,OLD.created_at)
          OR NEW.epoch<>OLD.epoch+1 OR NEW.fact_revision<>OLD.fact_revision+1
          OR target.previous_id IS DISTINCT FROM OLD.fact_id
          OR target.previous_revision IS DISTINCT FROM OLD.fact_revision THEN
          RAISE EXCEPTION 'Authority pointer and epoch must advance to the exact successor';
        END IF;
        RETURN NEW;
      END $function$

CREATE OR REPLACE FUNCTION public.protect_formal_verification_pointer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      DECLARE target verification_formal_requests%ROWTYPE;
      BEGIN
        IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Formal request history is retained'; END IF;
        SELECT * INTO target FROM verification_formal_requests
          WHERE id=NEW.request_version_id AND tenant_id=NEW.tenant_id
            AND product_id=NEW.product_id AND request_id=NEW.request_id;
        IF NOT FOUND OR target.revision<>NEW.request_revision THEN
          RAISE EXCEPTION 'Formal pointer must identify its exact request';
        END IF;
        IF TG_OP='INSERT' THEN
          IF NEW.request_revision<>1 OR target.previous_request_id IS NOT NULL THEN
            RAISE EXCEPTION 'Formal pointer must begin at first version';
          END IF;
        ELSIF ROW(NEW.id,NEW.tenant_id,NEW.product_id,NEW.request_id,NEW.created_at)
          IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.product_id,OLD.request_id,OLD.created_at)
          OR NEW.request_revision<>OLD.request_revision+1
          OR target.previous_request_id IS DISTINCT FROM OLD.request_version_id
          OR target.previous_revision IS DISTINCT FROM OLD.request_revision THEN
          RAISE EXCEPTION 'Formal pointer must advance to exact successor';
        END IF;
        RETURN NEW;
      END $function$

CREATE OR REPLACE FUNCTION public.protect_build_operational_fact()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      DECLARE prior build_operational_facts%ROWTYPE; plan builds%ROWTYPE;
      BEGIN
        SELECT * INTO plan FROM builds WHERE tenant_id=NEW.tenant_id AND id=NEW.build_id;
        IF NOT FOUND OR NEW.build_revision<>plan.revision THEN
          RAISE EXCEPTION 'Operational fact must bind exact Build revision'; END IF;
        IF NEW.revision>1 THEN
          SELECT * INTO prior FROM build_operational_facts WHERE id=NEW.previous_id
            AND tenant_id=NEW.tenant_id AND product_id=NEW.product_id;
          IF NOT FOUND OR ROW(NEW.project_id,NEW.build_id,NEW.build_revision,NEW.owner_id,
              NEW.visibility,NEW.issuer_key,NEW.nature,NEW.external_id,NEW.series_id,NEW.previous_revision)
            IS DISTINCT FROM ROW(prior.project_id,prior.build_id,prior.build_revision,prior.owner_id,
              prior.visibility,prior.issuer_key,prior.nature,prior.external_id,prior.series_id,prior.revision)
          THEN RAISE EXCEPTION 'Operational identity cannot be rebound'; END IF;
        END IF;
        RETURN NEW;
      END $function$

