CREATE OR REPLACE FUNCTION public.protect_verification_run_pointer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      DECLARE target verification_run_versions%ROWTYPE;
      BEGIN
        IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Run history is retained'; END IF;
        SELECT * INTO target FROM verification_run_versions WHERE tenant_id=NEW.tenant_id AND id=NEW.run_version_id;
        IF target.id IS NULL OR ROW(NEW.product_id,NEW.request_id,NEW.run_id,NEW.run_revision)
          IS DISTINCT FROM ROW(target.product_id,target.request_id,target.run_id,target.revision) THEN RAISE EXCEPTION 'Run current must match fixed version'; END IF;
        IF TG_OP='INSERT' THEN
          IF NEW.run_revision<>1 OR target.previous_run_version_id IS NOT NULL THEN RAISE EXCEPTION 'Run starts at first version'; END IF;
        ELSIF ROW(NEW.id,NEW.tenant_id,NEW.product_id,NEW.request_id,NEW.run_id,NEW.created_at)
          IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.product_id,OLD.request_id,OLD.run_id,OLD.created_at)
          OR NEW.run_revision<>OLD.run_revision+1 OR target.previous_run_version_id IS DISTINCT FROM OLD.run_version_id THEN
          RAISE EXCEPTION 'Run pointer advances to exact successor'; END IF;
        RETURN NEW;
      END $function$

CREATE OR REPLACE FUNCTION public.protect_sample_run_usage()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      DECLARE sample sample_units%ROWTYPE; actual actual_configurations%ROWTYPE;
      BEGIN
        SELECT * INTO sample FROM sample_units WHERE tenant_id=NEW.tenant_id AND id=NEW.sample_id;
        SELECT * INTO actual FROM actual_configurations WHERE tenant_id=NEW.tenant_id AND id=NEW.actual_configuration_id;
        IF sample.id IS NULL OR actual.id IS NULL OR ROW(NEW.product_id,NEW.project_id,NEW.build_id,NEW.sample_revision,NEW.actual_configuration_id)
          IS DISTINCT FROM ROW(sample.product_id,sample.project_id,sample.build_id,sample.revision,sample.actual_configuration_id)
          OR NEW.actual_configuration_revision<>actual.revision THEN RAISE EXCEPTION 'Sample use must bind exact physical actual configuration'; END IF;
        RETURN NEW;
      END $function$

CREATE OR REPLACE FUNCTION public.require_test_launch_atom()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      BEGIN
        IF TG_TABLE_NAME='verification_formal_requests' THEN
          IF NEW.operation IN ('test.results.import','test.run.review','test.disposition.decide') THEN
            IF NOT EXISTS (SELECT 1 FROM test_result_actions f WHERE f.tenant_id=NEW.tenant_id
              AND f.next_request_version_id=NEW.id AND f.operation=NEW.operation) THEN
              RAISE EXCEPTION 'Result request successor requires its exact named action'; END IF;
          ELSIF NEW.operation IN ('verification.schedule.promise','test.run.start') THEN
            IF NOT EXISTS (SELECT 1 FROM verification_launch_facts f WHERE f.tenant_id=NEW.tenant_id
              AND f.next_request_version_id=NEW.id AND f.operation=NEW.operation) THEN
              RAISE EXCEPTION 'Request launch successor requires its named fact'; END IF;
          END IF;
        ELSIF TG_TABLE_NAME='operational_resource_occupancies' THEN
          IF NEW.owner_kind='test_run' THEN PERFORM assert_test_run_atom(NEW.tenant_id,NEW.test_run_id); END IF;
        ELSIF TG_TABLE_NAME IN ('sample_run_usages','test_resource_reservations') THEN
          PERFORM assert_test_run_atom(NEW.tenant_id,NEW.run_id);
        ELSIF NEW.operation IN ('test.results.import','test.run.review','test.disposition.decide') THEN
          PERFORM assert_test_result_atom(NEW.tenant_id,NEW.id);
        ELSE
          IF NOT EXISTS (SELECT 1 FROM verification_launch_facts f WHERE f.tenant_id=NEW.tenant_id
              AND f.run_version_id=NEW.id AND f.operation=NEW.operation) THEN
            RAISE EXCEPTION 'Run version requires its launch fact'; END IF;
          IF NEW.status='running' THEN PERFORM assert_test_run_atom(NEW.tenant_id,NEW.run_id); END IF;
        END IF;
        RETURN NULL;
      END $function$

CREATE OR REPLACE FUNCTION public.require_test_result_atom()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      BEGIN
        IF TG_TABLE_NAME='test_result_actions' THEN
          PERFORM assert_test_result_atom(NEW.tenant_id,NEW.next_run_version_id);
        ELSE
          PERFORM assert_test_result_atom(NEW.tenant_id,NEW.run_version_id);
        END IF;
        RETURN NULL;
      END $function$

CREATE OR REPLACE FUNCTION public.protect_retained_artifact_state()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      BEGIN
        IF OLD.status='withdrawn' AND NEW.status IS DISTINCT FROM OLD.status THEN
          RAISE EXCEPTION 'Withdrawn source version is terminal; a new source needs a new identity';
        END IF;
        RETURN NEW;
      END $function$

CREATE OR REPLACE FUNCTION public.protect_quality_current()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target quality_issue_versions%ROWTYPE;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Issue identity pointer cannot be deleted'; END IF;
  SELECT * INTO target FROM quality_issue_versions WHERE tenant_id=NEW.tenant_id
    AND id=NEW.issue_version_id;
  IF target.id IS NULL OR ROW(target.product_id,target.project_id,target.issue_id,target.revision)
    IS DISTINCT FROM ROW(NEW.product_id,NEW.project_id,NEW.issue_id,NEW.issue_revision) THEN
    RAISE EXCEPTION 'Issue current requires its exact scoped version'; END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.issue_revision<>1 OR NEW.epoch<>1 THEN
      RAISE EXCEPTION 'Issue identity starts only at revision and epoch one'; END IF;
  ELSE
    IF ROW(NEW.id,NEW.tenant_id,NEW.product_id,NEW.project_id,NEW.issue_id,NEW.created_at)
      IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.product_id,OLD.project_id,OLD.issue_id,OLD.created_at)
      OR NEW.issue_revision<>OLD.issue_revision+1 OR NEW.epoch<>OLD.epoch+1
      OR target.previous_issue_version_id IS DISTINCT FROM OLD.issue_version_id
      OR target.previous_revision IS DISTINCT FROM OLD.issue_revision THEN
      RAISE EXCEPTION 'Issue current requires a continuous exact predecessor'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_change_current()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target change_request_versions%ROWTYPE;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Change pointer cannot be deleted'; END IF;
  SELECT * INTO target FROM change_request_versions WHERE tenant_id=NEW.tenant_id AND id=NEW.version_id;
  IF target.id IS NULL OR ROW(target.product_id,target.change_id,target.revision)
    IS DISTINCT FROM ROW(NEW.product_id,NEW.change_id,NEW.revision) THEN
    RAISE EXCEPTION 'Change current requires its exact scoped version'; END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.revision<>1 THEN RAISE EXCEPTION 'Change starts at revision one'; END IF;
  ELSE
    IF ROW(NEW.id,NEW.tenant_id,NEW.product_id,NEW.change_id,NEW.created_at)
      IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.product_id,OLD.change_id,OLD.created_at)
      OR NEW.revision<>OLD.revision+1 OR target.previous_version_id IS DISTINCT FROM OLD.version_id
      OR target.previous_revision IS DISTINCT FROM OLD.revision THEN
      RAISE EXCEPTION 'Change pointer requires a continuous exact predecessor'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_quality_followup_confirmation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE old_scoped boolean := false; new_scoped boolean := false;
BEGIN
  IF TG_OP<>'INSERT' THEN old_scoped := OLD.operation IN
    ('quality.issue.root_cause.decide','quality.capa.actions.complete','quality.capa.followup.link','quality.capa.observation.record','quality.capa.verification.review','quality.capa.verification.candidate.record'); END IF;
  IF TG_OP<>'DELETE' THEN new_scoped := NEW.operation IN
    ('quality.issue.root_cause.decide','quality.capa.actions.complete','quality.capa.followup.link','quality.capa.observation.record','quality.capa.verification.review','quality.capa.verification.candidate.record'); END IF;
  IF NOT (old_scoped OR new_scoped) THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.consumed IS DISTINCT FROM false THEN
      RAISE EXCEPTION 'Followup proof must be created unconsumed'; END IF;
    RETURN NEW;
  ELSIF TG_OP='DELETE' THEN
    IF OLD.consumed IS DISTINCT FROM false THEN
      RAISE EXCEPTION 'Consumed followup proof must be retained'; END IF;
    RETURN OLD;
  END IF;
  IF NOT (old_scoped AND new_scoped) OR OLD.consumed IS DISTINCT FROM false
    OR NEW.consumed IS DISTINCT FROM true
    OR (to_jsonb(NEW)-'consumed') IS DISTINCT FROM (to_jsonb(OLD)-'consumed') THEN
    RAISE EXCEPTION 'Followup proof only permits the exact unconsumed to consumed transition'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.assert_capa_publication_atom(table_name text, tid uuid, sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE n jsonb; body jsonb; anchor jsonb; original_id uuid; original_rev integer;
  op_name text; family text; tier_value text; kind_value text; c confirmations%ROWTYPE;
  r action_receipts%ROWTYPE; previous jsonb; dependency jsonb; child jsonb; actual_time timestamptz;
BEGIN
  CASE table_name
    WHEN 'capa_verification_rule_facts' THEN
      SELECT to_jsonb(f) INTO n FROM capa_verification_rule_facts f WHERE f.tenant_id=tid AND f.id=sid;
      op_name := 'quality.capa.verification.rule.import'; family := 'capa_verification_rule';
      tier_value := 'host_import'; kind_value := 'rule';
    WHEN 'capa_observation_facts' THEN
      SELECT to_jsonb(f) INTO n FROM capa_observation_facts f WHERE f.tenant_id=tid AND f.id=sid;
      op_name := 'quality.capa.observation.record'; family := 'capa_observation';
      tier_value := 'T1'; kind_value := 'observation';
    WHEN 'capa_named_verification_reviews' THEN
      SELECT to_jsonb(f) INTO n FROM capa_named_verification_reviews f WHERE f.tenant_id=tid AND f.id=sid;
      op_name := 'quality.capa.verification.review'; family := 'capa_named_verification_review';
      tier_value := 'T2'; kind_value := 'review';
    WHEN 'capa_verification_evidence' THEN
      SELECT to_jsonb(f) INTO n FROM capa_verification_evidence f WHERE f.tenant_id=tid AND f.id=sid;
      op_name := 'quality.capa.verification.candidate.record'; family := 'capa_verification_candidate';
      tier_value := 'T1'; kind_value := 'candidate';
    ELSE RAISE EXCEPTION 'Unsupported CAPA publication target';
  END CASE;
  IF n IS NULL OR NOT COALESCE(isfinite((n->>'created_at')::timestamptz),false)
    OR NOT EXISTS (SELECT 1 FROM principals WHERE tenant_id=tid
    AND id=(n->>'writer_id')::uuid AND kind='human' AND active)
    OR NOT EXISTS (SELECT 1 FROM grants WHERE tenant_id=tid
      AND product_id=(n->>'product_id')::uuid AND principal_id=(n->>'writer_id')::uuid
      AND can_write AND expires_at>(n->>'created_at')::timestamptz) THEN
    RAISE EXCEPTION 'CAPA publication requires exact target and named actual human'; END IF;
  IF kind_value='candidate' THEN
    anchor := n->'input_snapshot'->'stable_anchor';
    original_id := (n->>'issue_version_id')::uuid; original_rev := (n->>'issue_revision')::integer;
    IF NOT COALESCE(jsonb_typeof(n->'input_snapshot')='object'
      AND (n->'input_snapshot') ?& ARRAY['semantic','shared_proof','proof_consumed_at','stable_anchor']
      AND ((n->'input_snapshot')-ARRAY['semantic','shared_proof','proof_consumed_at','stable_anchor'])='{}'::jsonb
      AND jsonb_typeof(n->'input_snapshot'->'semantic')='object'
      AND n->>'owner_id'=anchor->'origin'->>'owner_id'
      AND n->>'visibility'=anchor->'origin'->>'visibility'
      AND ((n->'input_snapshot'->'shared_proof')-ARRAY['id','tier'])='{}'::jsonb
      AND NOT ((n->'input_snapshot'->'semantic') ? 'confirmation_token')
      AND NOT ((n->'input_snapshot'->'semantic') ? 'approval_token')
      AND n->'candidate_binding'->'basis'=n->'basis_snapshot'
      AND n->'candidate_snapshot'->'binding'=n->'candidate_binding'
      AND n->'candidate_snapshot'->>'inspection_sha256'=n->>'inspection_sha256'
      AND n->'basis_snapshot'->>'basis_sha256'=n->>'basis_sha256'
      AND n->'candidate_snapshot'->'required_source_read_set'=n->'required_source_read_set',false) THEN
      RAISE EXCEPTION 'Candidate requires exact frozen unknown binding/inspection and no-token semantic'; END IF;
    PERFORM assert_capa_fact_source_closure(tid,(n->>'product_id')::uuid,n->'sources',n->'required_source_read_set',
      n->'source_basis'->'artifact_sources',n->>'visibility',(n->>'owner_id')::uuid);
    c := assert_quality_followup_proof(tid,(n->>'product_id')::uuid,(n->>'writer_id')::uuid,
      op_name,n->'input_snapshot'->'shared_proof',(n->>'created_at')::timestamptz);
    IF NOT COALESCE(jsonb_typeof(n->'input_snapshot'->'proof_consumed_at')='string'
      AND n->'input_snapshot'->>'proof_consumed_at' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*(Z|[+-][0-9]{2}:[0-9]{2})$'
      AND c.created_at<=(n->'input_snapshot'->>'proof_consumed_at')::timestamptz
      AND (n->'input_snapshot'->>'proof_consumed_at')::timestamptz<=(n->>'created_at')::timestamptz,false) THEN
      RAISE EXCEPTION 'Candidate retains actual consumed and saved clocks'; END IF;
  ELSE
    body := n->'fact_body'->'body'; anchor := n->'anchor_snapshot';
    original_id := (n->>'origin_issue_version_id')::uuid;
    original_rev := (n->>'origin_issue_revision')::integer;
    IF n->>'operation' IS DISTINCT FROM op_name OR n->>'tier' IS DISTINCT FROM tier_value
      OR n->>'fact_kind' IS DISTINCT FROM kind_value
      OR ROW(n->>'actor_id',n->>'requester_id') IS DISTINCT FROM ROW(n->>'writer_id',n->>'writer_id') THEN
      RAISE EXCEPTION 'CAPA fact actual operation, tier and writer must match'; END IF;
    PERFORM assert_capa_fact_source_closure(tid,(n->>'product_id')::uuid,n->'sources',n->'required_source_read_set',
      n->'source_basis',n->>'visibility',(n->>'owner_id')::uuid);
    IF tier_value<>'host_import' THEN
      c := assert_quality_followup_proof(tid,(n->>'product_id')::uuid,(n->>'writer_id')::uuid,
        op_name,jsonb_build_object('id',n->'shared_proof_id','tier',tier_value),(n->>'created_at')::timestamptz);
      IF NOT COALESCE((n->>'shared_proof_revision')::integer=c.revision
        AND (n->>'proof_expires_at')::timestamptz=c.expires_at AND n->>'token_sha256'=c.token_hash
        AND n->>'material_sha256'=c.payload_digest AND c.created_at<=(n->>'proof_consumed_at')::timestamptz
        AND (n->>'proof_consumed_at')::timestamptz<=(n->>'created_at')::timestamptz,false) THEN
        RAISE EXCEPTION 'CAPA fact requires exact actual shared proof fields and consumption clock'; END IF;
    END IF;
  END IF;
  PERFORM assert_capa_fact_origin(tid,(n->>'product_id')::uuid,(n->>'project_id')::uuid,
    (n->>'issue_id')::uuid,(n->>'capa_id')::uuid,original_id,original_rev,n->>'purpose',n->>'nature',
    anchor,n->'required_source_read_set',n->>'visibility',(n->>'writer_id')::uuid);
  IF kind_value IN ('rule','observation') AND n->>'previous_fact_id' IS NOT NULL THEN
    IF kind_value='rule' THEN
      SELECT to_jsonb(f) INTO previous FROM capa_verification_rule_facts f
        WHERE f.tenant_id=tid AND f.id=(n->>'previous_fact_id')::uuid;
    ELSE
      SELECT to_jsonb(f) INTO previous FROM capa_observation_facts f
        WHERE f.tenant_id=tid AND f.id=(n->>'previous_fact_id')::uuid;
    END IF;
    IF previous IS NULL OR previous->>'purpose' IS DISTINCT FROM n->>'purpose' THEN
      RAISE EXCEPTION 'CAPA successor retains exact complete original purpose'; END IF;
  END IF;
  r := assert_quality_followup_receipt(tid,(n->>'product_id')::uuid,sid,(n->>'revision')::integer,
    op_name,family,(n->>'writer_id')::uuid,n->>'visibility',n->>'status');
  IF jsonb_typeof(r.result->'revision') IS DISTINCT FROM 'number'
    OR NOT COALESCE(r.result->>'revision' ~ '^[1-9][0-9]*$',false)
    OR r.result->'revision' IS DISTINCT FROM n->'revision'
    OR r.created_at<(n->>'created_at')::timestamptz THEN
    RAISE EXCEPTION 'CAPA receipt retains exact numeric revision and actual save ordering'; END IF;
  IF r.intent_digest IS DISTINCT FROM n->>'intent_digest' THEN
    RAISE EXCEPTION 'CAPA publication uses actual common intent, not domain intent'; END IF;
  IF tier_value<>'host_import' AND (c.snapshot->>'operation' IS DISTINCT FROM op_name
    OR c.snapshot->'required_source_read_set' IS DISTINCT FROM n->'required_source_read_set') THEN
    RAISE EXCEPTION 'CAPA proof review retains operation and exact complete read set'; END IF;
  IF kind_value='candidate' THEN
    IF (r.result-ARRAY['id','revision','status','candidate_binding_sha256','inspection_sha256'])<>'{}'::jsonb
      OR r.result->>'candidate_binding_sha256' IS DISTINCT FROM n->>'binding_sha256'
      OR r.result->>'inspection_sha256' IS DISTINCT FROM n->>'inspection_sha256' THEN
      RAISE EXCEPTION 'Candidate receipt binds actual non-cyclic binding and inspection hashes'; END IF;
  ELSE
    IF (r.result-ARRAY['id','revision','status','fact_kind','payload_sha256'])<>'{}'::jsonb
      OR r.command_id IS DISTINCT FROM (n->>'command_id')::uuid
      OR r.result->>'fact_kind' IS DISTINCT FROM kind_value
      OR r.result->>'payload_sha256' IS DISTINCT FROM n->>'payload_sha256' THEN
      RAISE EXCEPTION 'CAPA fact receipt binds actual command and body payload hash'; END IF;
  END IF;
  IF kind_value IN ('rule','observation') THEN
    IF kind_value='rule' THEN
      IF NOT COALESCE(isfinite((n->>'valid_from')::timestamptz)
        AND isfinite((n->>'valid_until')::timestamptz),false) THEN
        RAISE EXCEPTION 'Rule publication retains finite fixed validity clocks'; END IF;
      IF NOT EXISTS (SELECT 1 FROM capa_current_verification_rules p WHERE p.tenant_id=tid
        AND p.product_id=(n->>'product_id')::uuid AND p.project_id=(n->>'project_id')::uuid
        AND p.issue_id=(n->>'issue_id')::uuid AND p.capa_id=(n->>'capa_id')::uuid
        AND p.series_id=(n->>'series_id')::uuid AND p.fact_id=sid
        AND p.fact_revision=(n->>'revision')::integer) THEN
        RAISE EXCEPTION 'Rule publication and its exact Current must commit together'; END IF;
      IF n->>'previous_fact_id' IS NOT NULL THEN
        SELECT to_jsonb(f) INTO previous FROM capa_verification_rule_facts f
          WHERE f.tenant_id=tid AND f.id=(n->>'previous_fact_id')::uuid;
        IF previous->>'issuer_key' IS DISTINCT FROM n->>'issuer_key'
          OR previous->>'external_id' IS DISTINCT FROM n->>'external_id'
          OR (n->>'issuer_epoch')::integer<(previous->>'issuer_epoch')::integer THEN
          RAISE EXCEPTION 'Rule successor preserves external series and cannot rewind issuer epoch'; END IF;
      END IF;
    ELSE
      IF NOT EXISTS (SELECT 1 FROM capa_current_observations p WHERE p.tenant_id=tid
        AND p.product_id=(n->>'product_id')::uuid AND p.project_id=(n->>'project_id')::uuid
        AND p.issue_id=(n->>'issue_id')::uuid AND p.capa_id=(n->>'capa_id')::uuid
        AND p.series_id=(n->>'series_id')::uuid AND p.fact_id=sid
        AND p.fact_revision=(n->>'revision')::integer) THEN
        RAISE EXCEPTION 'Observation and its exact Current must commit together'; END IF;
      actual_time := (body->'at'->>'occurred_at')::timestamptz;
      IF NOT COALESCE((n->>'observed_from')::timestamptz<(n->>'observed_until')::timestamptz
        AND (n->>'observed_until')::timestamptz<=actual_time
        AND actual_time<=(n->>'created_at')::timestamptz
        AND jsonb_typeof(body->'records')='array' AND jsonb_array_length(body->'records')>0
        AND jsonb_typeof(body->'targets')='array' AND jsonb_array_length(body->'targets')>0,false)
        OR EXISTS (SELECT 1 FROM jsonb_array_elements(body->'records') x WHERE NOT COALESCE(
          (x->>'occurred_at')::timestamptz BETWEEN (n->>'observed_from')::timestamptz
            AND (n->>'observed_until')::timestamptz
          AND EXISTS (SELECT 1 FROM jsonb_array_elements(body->'targets') t WHERE t->>'key'=x->>'target_key'),false)) THEN
        RAISE EXCEPTION 'Observation retains actual target records and original received time'; END IF;
    END IF;
  END IF;
  IF kind_value IN ('observation','review') THEN
    SELECT to_jsonb(f) INTO dependency FROM capa_verification_rule_facts f WHERE f.tenant_id=tid
      AND f.product_id=(n->>'product_id')::uuid AND f.project_id=(n->>'project_id')::uuid
      AND f.issue_id=(n->>'issue_id')::uuid AND f.capa_id=(n->>'capa_id')::uuid
      AND f.id=(n->>'rule_fact_id')::uuid AND f.revision=(n->>'rule_revision')::integer;
    IF dependency IS NULL OR ROW(dependency->>'anchor_sha256',dependency->>'requirement_sha256',
      dependency->>'purpose',dependency->>'nature') IS DISTINCT FROM ROW(n->>'anchor_sha256',
      n->>'requirement_sha256',n->>'purpose',n->>'nature') THEN
      RAISE EXCEPTION 'CAPA observation/review requires exact scoped published Rule'; END IF;
  END IF;
  IF kind_value='review' THEN
    IF NOT COALESCE(isfinite((body->'at'->>'occurred_at')::timestamptz)
      AND (body->'at'->>'occurred_at')::timestamptz<=(n->>'created_at')::timestamptz
      AND isfinite((n->>'valid_until')::timestamptz),false)
      OR NOT EXISTS (SELECT 1 FROM capa_verification_evidence f WHERE f.tenant_id=tid
      AND f.product_id=(n->>'product_id')::uuid AND f.project_id=(n->>'project_id')::uuid
      AND f.issue_id=(n->>'issue_id')::uuid AND f.capa_id=(n->>'capa_id')::uuid
      AND f.id=(n->>'candidate_id')::uuid AND f.revision=(n->>'candidate_revision')::integer
      AND f.input_snapshot->'stable_anchor'=anchor AND f.purpose=n->>'purpose' AND f.nature=n->>'nature')
      OR NOT COALESCE(jsonb_typeof(body->'observations')='array'
        AND jsonb_array_length(body->'observations')>0
        AND jsonb_array_length(body->'observations')=(SELECT count(DISTINCT x->>'id')
          FROM jsonb_array_elements(body->'observations') x),false) THEN
      RAISE EXCEPTION 'Named review requires exact scoped candidate and unique ordered observation refs'; END IF;
    FOR child IN SELECT value FROM jsonb_array_elements(body->'observations') LOOP
      IF NOT EXISTS (SELECT 1 FROM capa_observation_facts f WHERE f.tenant_id=tid
        AND f.product_id=(n->>'product_id')::uuid AND f.project_id=(n->>'project_id')::uuid
        AND f.issue_id=(n->>'issue_id')::uuid AND f.capa_id=(n->>'capa_id')::uuid
        AND f.id=(child->>'id')::uuid AND f.revision=(child->>'revision')::integer
        AND f.rule_fact_id=(n->>'rule_fact_id')::uuid AND f.rule_revision=(n->>'rule_revision')::integer
        AND f.rule_sha256=n->>'rule_sha256' AND f.anchor_sha256=n->>'anchor_sha256'
        AND f.requirement_sha256=n->>'requirement_sha256' AND f.purpose=n->>'purpose' AND f.nature=n->>'nature'
        AND (f.fact_body->'body'->'at'->>'occurred_at')::timestamptz<=(body->'at'->>'occurred_at')::timestamptz) THEN
        RAISE EXCEPTION 'Named review requires every exact original observation in the saved scope'; END IF;
    END LOOP;
  END IF;
  -- Canonical body/full SHA, original bytes, full child FactRef SHA, actual
  -- semantic material and seven current owner gates remain host responsibilities.
END $function$

CREATE OR REPLACE FUNCTION public.require_change_order_parent_atom()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE count_atoms integer;
BEGIN
  IF NEW.operation NOT IN ('change.order.prepare','change.order.approve','change.implementation.record') THEN RETURN NULL; END IF;
  SELECT count(*) INTO count_atoms FROM (
    SELECT tenant_id,product_id,change_version_id,change_revision,operation FROM change_order_records
    UNION ALL SELECT tenant_id,product_id,change_version_id,change_revision,operation FROM change_approval_records
    UNION ALL SELECT tenant_id,product_id,change_version_id,change_revision,operation FROM change_implementation_records
  ) AS atoms WHERE atoms.tenant_id=NEW.tenant_id AND atoms.product_id=NEW.product_id
    AND atoms.change_version_id=NEW.id AND atoms.change_revision=NEW.revision AND atoms.operation=NEW.operation;
  IF count_atoms<>1 THEN RAISE EXCEPTION 'missing exact change child atom' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.require_change_order_proof_atom()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE count_atoms integer;
BEGIN
  IF NEW.operation NOT IN ('change.order.prepare','change.order.approve','change.implementation.record') OR NOT NEW.consumed THEN RETURN NULL; END IF;
  SELECT count(*) INTO count_atoms FROM (
    SELECT tenant_id,product_id,shared_proof_id,actor_id,operation FROM change_order_records
    UNION ALL SELECT tenant_id,product_id,shared_proof_id,actor_id,operation FROM change_approval_records
    UNION ALL SELECT tenant_id,product_id,shared_proof_id,actor_id,operation FROM change_implementation_records
  ) AS atoms WHERE atoms.tenant_id=NEW.tenant_id AND atoms.product_id=NEW.product_id
    AND atoms.shared_proof_id=NEW.id AND atoms.actor_id=NEW.actor_id AND atoms.operation=NEW.operation;
  IF count_atoms<>1 THEN RAISE EXCEPTION 'consumed proof missing unique change atom' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.protect_controlled_change_current()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE f jsonb; oldj jsonb; newj jsonb:=to_jsonb(NEW); target_table text;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'controlled Current retained'; END IF;
  target_table:=CASE TG_TABLE_NAME WHEN 'controlled_change_policy_currents'
    THEN 'controlled_change_policy_facts' WHEN 'controlled_change_selection_currents'
    THEN 'controlled_change_selection_facts' END;
  IF target_table IS NULL THEN RAISE EXCEPTION 'unknown controlled Current'; END IF;
  EXECUTE format('SELECT to_jsonb(f) FROM public.%I f WHERE tenant_id=$1 AND id=$2',target_table)
    INTO STRICT f USING NEW.tenant_id,NEW.fact_id;
  IF ROW(NEW.tenant_id,NEW.product_id,NEW.project_id,NEW.owner_id,NEW.visibility,
    NEW.purpose_sha256,NEW.revision,NEW.epoch) IS DISTINCT FROM
    ROW((f->>'tenant_id')::uuid,(f->>'product_id')::uuid,(f->>'project_id')::uuid,
      (f->>'owner_id')::uuid,f->>'visibility',f->>'purpose_sha256',
      (f->>'revision')::integer,(f->>'epoch')::integer)
    OR (target_table='controlled_change_selection_facts' AND
      ROW(newj->>'change_id',newj->>'item_id') IS DISTINCT FROM ROW(f->>'change_id',f->>'item_id'))
    THEN RAISE EXCEPTION 'controlled Current target mismatch'; END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.revision<>1 OR NEW.epoch<>1 OR f->>'previous_id' IS NOT NULL
      OR f->>'previous_revision' IS NOT NULL THEN RAISE EXCEPTION 'Current not initial'; END IF;
  ELSE
    oldj:=to_jsonb(OLD);
    IF (newj-ARRAY['fact_id','revision','epoch']) IS DISTINCT FROM
      (oldj-ARRAY['fact_id','revision','epoch'])
      OR NEW.revision<>OLD.revision+1 OR NEW.epoch<>OLD.epoch+1
      OR (f->>'previous_id')::uuid IS DISTINCT FROM OLD.fact_id
      OR (f->>'previous_revision')::integer IS DISTINCT FROM OLD.revision
      THEN RAISE EXCEPTION 'Current continuous exact series required'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.require_change_receipt_atom()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE tab text; n integer;
BEGIN
  IF NEW.operation IN ('change.policy.import','change.selection.decide') THEN
    tab:=CASE NEW.operation WHEN 'change.policy.import' THEN 'controlled_change_policy_facts'
      ELSE 'controlled_change_selection_facts' END;
    PERFORM assert_controlled_change_atom(tab,NEW.tenant_id,NEW.subject_id);
  ELSIF NEW.operation IN ('change.order.prepare','change.order.approve','change.implementation.record') THEN
    SELECT count(*) INTO n FROM (
      SELECT tenant_id,product_id,change_version_id,change_revision,operation FROM change_order_records
      UNION ALL SELECT tenant_id,product_id,change_version_id,change_revision,operation FROM change_approval_records
      UNION ALL SELECT tenant_id,product_id,change_version_id,change_revision,operation FROM change_implementation_records
    ) a WHERE a.tenant_id=NEW.tenant_id AND a.product_id=NEW.product_id
      AND a.change_version_id=NEW.subject_id AND a.change_revision=NEW.subject_revision
      AND a.operation=NEW.operation;
    IF n<>1 OR NEW.subject_type<>'change_request' THEN RAISE EXCEPTION 'receipt has no exact change atom'; END IF;
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.require_selection_proof_atom()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$ DECLARE n integer;
BEGIN
  IF NEW.operation<>'change.selection.decide' OR NOT NEW.consumed THEN RETURN NULL; END IF;
  SELECT count(*) INTO n FROM controlled_change_selection_facts a WHERE a.tenant_id=NEW.tenant_id
    AND a.product_id=NEW.product_id AND a.actor_id=NEW.actor_id AND a.shared_proof_id=NEW.id;
  IF n<>1 THEN RAISE EXCEPTION 'consumed selection proof needs exact atom'; END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.protect_change_confirmation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$ BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.operation IN ('change.order.prepare','change.order.approve','change.implementation.record','change.selection.decide') THEN RAISE EXCEPTION 'change proof retained'; END IF; RETURN OLD;
  END IF;
  IF TG_OP='INSERT' AND NEW.operation NOT IN ('change.order.prepare','change.order.approve','change.implementation.record','change.selection.decide') THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND OLD.operation NOT IN ('change.order.prepare','change.order.approve','change.implementation.record','change.selection.decide')
    AND NEW.operation NOT IN ('change.order.prepare','change.order.approve','change.implementation.record','change.selection.decide') THEN RETURN NEW; END IF;
  IF TG_OP='INSERT' AND NEW.consumed THEN RAISE EXCEPTION 'new proof cannot be pre-consumed'; END IF;
  IF TG_OP='UPDATE' AND ((to_jsonb(NEW)-'consumed') IS DISTINCT FROM (to_jsonb(OLD)-'consumed')
    OR (OLD.consumed AND NOT NEW.consumed)) THEN RAISE EXCEPTION 'consumed change proof immutable'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_manufacturing_preparation_proof()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE old_scoped boolean; new_scoped boolean;
BEGIN
 IF TG_OP='DELETE' THEN
   IF OLD.operation IN ('npi.work_instruction.record','npi.control_plan.record',
'npi.manufacturing_baseline.record') THEN
     RAISE EXCEPTION 'Preparation proof history is retained'; END IF;
   RETURN OLD;
 END IF;
 new_scoped := NEW.operation IN ('npi.work_instruction.record', 'npi.control_plan.record',
'npi.manufacturing_baseline.record');
 IF TG_OP='INSERT' THEN
   IF new_scoped AND NEW.consumed IS DISTINCT FROM false THEN
     RAISE EXCEPTION 'Manufacturing preparation proof must begin unconsumed'; END IF;
   RETURN NEW;
 END IF;
 old_scoped := OLD.operation IN ('npi.work_instruction.record', 'npi.control_plan.record',
'npi.manufacturing_baseline.record');
 IF NOT (old_scoped OR new_scoped) THEN RETURN NEW; END IF;
 IF NOT(old_scoped AND new_scoped) OR OLD.consumed IS DISTINCT FROM false
    OR NEW.consumed IS DISTINCT FROM true
    OR (to_jsonb(NEW)-'consumed') IS DISTINCT FROM (to_jsonb(OLD)-'consumed') THEN
   RAISE EXCEPTION 'Preparation proof permits only original false to true'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.require_manufacturing_preparation_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE used integer;
BEGIN
 IF NEW.operation NOT IN ('npi.work_instruction.record', 'npi.control_plan.record',
'npi.manufacturing_baseline.record')
   THEN RETURN NULL; END IF;
 IF OLD.consumed IS DISTINCT FROM false OR NEW.consumed IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'Preparation target requires actual transition'; END IF;
 SELECT count(*) INTO used FROM manufacturing_preparation_versions v
 WHERE v.tenant_id=NEW.tenant_id AND v.shared_proof_id=NEW.id;
 IF used<>1 THEN RAISE EXCEPTION 'One transitioned preparation proof requires one new target';
END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.require_manufacturing_preparation_member()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r action_receipts%ROWTYPE;
BEGIN
 SELECT * INTO r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id;
 IF FOUND AND (r.operation IN ('npi.work_instruction.record','npi.control_plan.record',
 'npi.manufacturing_baseline.record') OR r.subject_type IN
 ('work_instruction','control_plan','manufacturing_baseline')) THEN
 PERFORM assert_manufacturing_preparation_members(NEW.tenant_id,r.subject_id); END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.protect_manufacturing_preparation_member()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE n jsonb; o jsonb; scoped boolean; old_scoped boolean;
BEGIN
 IF TG_OP<>'DELETE' THEN n=to_jsonb(NEW); END IF;
 IF TG_OP<>'INSERT' THEN o=to_jsonb(OLD); END IF;
 SELECT EXISTS(SELECT 1 FROM action_receipts WHERE tenant_id=(n->>'tenant_id')::uuid
 AND id=(n->>'receipt_id')::uuid AND (operation IN
 ('npi.work_instruction.record','npi.control_plan.record','npi.manufacturing_baseline.record')
 OR subject_type IN ('work_instruction','control_plan','manufacturing_baseline'))) INTO scoped;
 SELECT EXISTS(SELECT 1 FROM action_receipts WHERE tenant_id=(o->>'tenant_id')::uuid
 AND id=(o->>'receipt_id')::uuid AND (operation IN
 ('npi.work_instruction.record','npi.control_plan.record','npi.manufacturing_baseline.record')
 OR subject_type IN ('work_instruction','control_plan','manufacturing_baseline')))
 INTO old_scoped;
 IF TG_OP='INSERT' OR NOT(scoped OR old_scoped) THEN
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Preparation common history is retained'; END IF;
 IF TG_TABLE_NAME='outbox_events' THEN
 IF (n-ARRAY['delivered_at','lease_id','lease_until','attempts','last_error'])
 IS DISTINCT FROM (o-ARRAY['delivered_at','lease_id','lease_until','attempts','last_error']) THEN
 RAISE EXCEPTION 'Only delivery state may update preparation Outbox'; END IF;
 ELSE
 RAISE EXCEPTION 'Preparation Audit/RequestKey is immutable'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.require_test_resource_dependency_atom()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE rid uuid; original verification_run_versions%ROWTYPE;
 saved test_resource_reservations%ROWTYPE; rec action_receipts%ROWTYPE;
 inserted jsonb;
BEGIN
 rid := NEW.run_id;
 inserted := to_jsonb(NEW);
 IF TG_TABLE_NAME='verification_run_versions' AND inserted->>'operation'='test.run.plan' THEN
   RETURN NULL;
 END IF;
 SELECT * INTO saved FROM test_resource_reservations
 WHERE tenant_id=NEW.tenant_id AND run_id=rid;
 SELECT * INTO original FROM verification_run_versions
 WHERE tenant_id=NEW.tenant_id AND run_id=rid AND revision=2 AND operation='test.run.start';
 IF saved.fingerprint_version IS NULL AND saved.dependency_proof IS NULL THEN
   IF original.input_snapshot ?| ARRAY['resource_fingerprint_version','resource_dependency_proof']
     OR (TG_TABLE_NAME='verification_run_versions'
         AND (inserted->'input_snapshot') ?| ARRAY['resource_fingerprint_version','resource_dependency_proof']) THEN
     RAISE EXCEPTION 'Explicit dependency version cannot fall back to legacy storage';
   END IF;
   RETURN NULL;
 END IF;
 IF saved.id IS NULL OR original.id IS NULL
   OR saved.fingerprint_version IS DISTINCT FROM 'test-resource-dependency-v2'
   OR original.input_snapshot->>'resource_fingerprint_version' IS DISTINCT FROM saved.fingerprint_version
   OR original.input_snapshot->'resource_dependency_proof' IS DISTINCT FROM saved.dependency_proof
   OR original.input_snapshot->>'resource_facts_revision' IS DISTINCT FROM saved.facts_revision
   OR original.input_snapshot->'reservation'->>'facts_revision' IS DISTINCT FROM saved.facts_revision
   OR original.input_snapshot->'reservation'->>'reservation_id' IS DISTINCT FROM saved.id::text
   OR original.input_snapshot->'reservation'->>'owner_run_id' IS DISTINCT FROM saved.run_id::text
   OR saved.dependency_proof->'material'->'binding'->>'run_id' IS DISTINCT FROM saved.run_id::text
   OR saved.dependency_proof->'material'->'binding'->>'project_id' IS DISTINCT FROM saved.project_id::text
   OR saved.dependency_proof->'material'->'binding'->>'build_id' IS DISTINCT FROM saved.build_id::text
   OR saved.dependency_proof->'material'->'authority'->'scope'->>'tenant_id' IS DISTINCT FROM saved.tenant_id::text
   OR saved.dependency_proof->'material'->'authority'->'scope'->>'product_id' IS DISTINCT FROM saved.product_id::text THEN
   RAISE EXCEPTION 'Versioned dependency requires the exact immutable Start and saved reservation';
 END IF;
 IF TG_TABLE_NAME='verification_run_versions' AND (
   inserted->'input_snapshot'->>'resource_fingerprint_version' IS DISTINCT FROM saved.fingerprint_version
   OR inserted->'input_snapshot'->'resource_dependency_proof' IS DISTINCT FROM saved.dependency_proof
   OR inserted->'input_snapshot'->>'resource_facts_revision' IS DISTINCT FROM saved.facts_revision
   OR inserted->'input_snapshot'->'reservation' IS DISTINCT FROM original.input_snapshot->'reservation') THEN
   RAISE EXCEPTION 'Run successor must preserve the original full resource proof';
 END IF;
 PERFORM assert_test_run_atom(NEW.tenant_id,rid);
 SELECT * INTO rec FROM action_receipts WHERE tenant_id=NEW.tenant_id
   AND product_id=original.product_id AND subject_type='test_run'
   AND subject_id=original.id AND subject_revision=original.revision
   AND operation='test.run.start' AND actor_id=original.writer_id
   AND requester_id=original.writer_id;
 IF rec.id IS NULL
   OR NOT EXISTS(SELECT 1 FROM request_keys k WHERE k.tenant_id=rec.tenant_id
     AND k.receipt_id=rec.id AND k.actor_id=rec.actor_id AND k.digest=rec.request_digest)
   OR NOT EXISTS(SELECT 1 FROM audit_entries a WHERE a.tenant_id=rec.tenant_id
     AND a.receipt_id=rec.id AND a.actor_id=rec.actor_id AND a.operation=rec.operation)
   OR NOT EXISTS(SELECT 1 FROM outbox_events o WHERE o.tenant_id=rec.tenant_id
     AND o.receipt_id=rec.id AND o.actor_id=rec.actor_id AND o.subject_id=original.id
     AND o.subject_revision=original.revision AND o.type='test.run_started') THEN
   RAISE EXCEPTION 'Versioned Start requires its common receipt, request key, audit and outbox atom';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.protect_change_dependency_clock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF pg_trigger_depth()<2 OR TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Dependency clock is maintained only by actual owner triggers';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.epoch<>1 OR NEW.id<>NEW.product_id THEN
   RAISE EXCEPTION 'Dependency clock must start at its product identity'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-'epoch') IS DISTINCT FROM (to_jsonb(OLD)-'epoch')
  OR NEW.epoch<>OLD.epoch+1 THEN
  RAISE EXCEPTION 'Dependency clock scope is fixed and epoch is monotonic'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.advance_change_dependency_clock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v jsonb; t uuid; p uuid;
BEGIN
 IF TG_OP='DELETE' THEN v=to_jsonb(OLD); ELSE v=to_jsonb(NEW); END IF;
 t=(v->>'tenant_id')::uuid; p=(v->>'product_id')::uuid;
 IF TG_TABLE_NAME='operational_asset_sentinels' THEN
  -- Shared physical assets have no product_id. Conservatively fence every
  -- product of their actual tenant, including references not yet consumed.
  -- Only clock rows are locked here: taking other Product locks after a
  -- command's own Product would invert the existing common lock order.
  IF t IS NULL THEN RAISE EXCEPTION 'Shared dependency tenant is missing'; END IF;
  FOR p IN SELECT product_id FROM public.change_dependency_clocks
   WHERE tenant_id=t ORDER BY product_id LOOP
   UPDATE public.change_dependency_clocks SET epoch=epoch+1
    WHERE tenant_id=t AND product_id=p;
  END LOOP;
  RETURN NULL;
 END IF;
 IF TG_OP='UPDATE' AND ROW(t,p) IS DISTINCT FROM
  ROW((to_jsonb(OLD)->>'tenant_id')::uuid,(to_jsonb(OLD)->>'product_id')::uuid) THEN
  RAISE EXCEPTION 'Dependency scope cannot be reassigned'; END IF;
 PERFORM 1 FROM public.products WHERE tenant_id=t AND id=p FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Actual dependency Product is missing'; END IF;
 UPDATE public.change_dependency_clocks SET epoch=epoch+1
  WHERE tenant_id=t AND product_id=p;
 IF NOT FOUND THEN RAISE EXCEPTION 'Actual product dependency clock is missing'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.protect_change_coverage_current()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE f public.controlled_change_coverage_facts%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'coverage Current history is retained'; END IF;
 SELECT * INTO STRICT f FROM public.controlled_change_coverage_facts
  WHERE tenant_id=NEW.tenant_id AND id=NEW.fact_id;
 IF ROW(NEW.tenant_id,NEW.product_id,NEW.project_id,NEW.owner_id,NEW.visibility,NEW.change_id,
  NEW.purpose_sha256,NEW.revision,NEW.epoch) IS DISTINCT FROM
  ROW(f.tenant_id,f.product_id,f.project_id,f.owner_id,f.visibility,f.change_id,
   f.purpose_sha256,f.revision,f.epoch) THEN RAISE EXCEPTION 'coverage Current exact target required'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.revision<>1 OR NEW.epoch<>1 OR f.previous_id IS NOT NULL OR f.previous_revision IS NOT NULL
  THEN RAISE EXCEPTION 'coverage Current must begin at exact initial publication'; END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['fact_id','revision','epoch']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['fact_id','revision','epoch'])
   OR NEW.revision<>OLD.revision+1 OR NEW.epoch<>OLD.epoch+1
   OR f.previous_id IS DISTINCT FROM OLD.fact_id OR f.previous_revision IS DISTINCT FROM OLD.revision
  THEN RAISE EXCEPTION 'coverage Current must advance exactly one immutable publication'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_change_coverage_common()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE oldj jsonb:=to_jsonb(OLD); newj jsonb; scoped boolean;
BEGIN
 IF TG_OP='UPDATE' THEN newj:=to_jsonb(NEW); END IF;
 IF TG_TABLE_NAME='action_receipts' THEN
  scoped:=oldj->>'operation'='change.coverage.import' OR oldj->>'subject_type'='change_coverage_fact'
   OR newj->>'operation'='change.coverage.import' OR newj->>'subject_type'='change_coverage_fact';
 ELSE
  SELECT EXISTS(SELECT 1 FROM public.action_receipts r
   WHERE (r.tenant_id,r.id) IN ((OLD.tenant_id,(oldj->>'receipt_id')::uuid),
     ((newj->>'tenant_id')::uuid,(newj->>'receipt_id')::uuid))
    AND (r.operation='change.coverage.import' OR r.subject_type='change_coverage_fact')) INTO scoped;
 END IF;
 IF NOT COALESCE(scoped,false) THEN
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'coverage common history is retained'; END IF;
 IF TG_TABLE_NAME='outbox_events' THEN
  IF (newj-ARRAY['delivered_at','lease_id','lease_until','attempts','last_error']) IS DISTINCT FROM
    (oldj-ARRAY['delivered_at','lease_id','lease_until','attempts','last_error'])
  THEN RAISE EXCEPTION 'coverage Outbox publication header is immutable'; END IF;
 ELSIF newj IS DISTINCT FROM oldj THEN
  RAISE EXCEPTION 'coverage common publication is immutable';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.require_change_coverage_atom()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE payload jsonb; rec public.action_receipts%ROWTYPE;
 a public.controlled_change_coverage_facts%ROWTYPE; target uuid; epoch_now bigint;
BEGIN
 IF TG_OP='DELETE' THEN payload:=to_jsonb(OLD); ELSE payload:=to_jsonb(NEW); END IF;
 IF TG_TABLE_NAME='controlled_change_coverage_facts' THEN target:=(payload->>'id')::uuid;
 ELSIF TG_TABLE_NAME='controlled_change_coverage_currents' THEN target:=(payload->>'fact_id')::uuid;
 ELSE
  IF TG_TABLE_NAME='action_receipts' THEN rec:=NEW;
  ELSE SELECT * INTO rec FROM public.action_receipts WHERE tenant_id=(payload->>'tenant_id')::uuid
   AND id=(payload->>'receipt_id')::uuid; END IF;
  IF rec.id IS NULL OR NOT (rec.operation='change.coverage.import' OR rec.subject_type='change_coverage_fact')
  THEN RETURN NULL; END IF;
  IF rec.operation<>'change.coverage.import' OR rec.subject_type<>'change_coverage_fact' THEN
   RAISE EXCEPTION 'coverage receipt family/operation mismatch'; END IF;
  target:=rec.subject_id;
 END IF;
 PERFORM public.assert_change_coverage_atom((payload->>'tenant_id')::uuid,target);
 -- Current publication fences only apply to a new Fact/Current event. Old
 -- Outbox delivery or lawful alias-key insertion retains its stored atom even
 -- after unrelated dependency changes; actual recovery still rechecks owners.
 IF TG_TABLE_NAME IN ('controlled_change_coverage_facts','controlled_change_coverage_currents') THEN
  SELECT * INTO STRICT a FROM public.controlled_change_coverage_facts
   WHERE tenant_id=(payload->>'tenant_id')::uuid AND id=target;
  epoch_now:=public.lock_change_dependency_clock(a.tenant_id,a.product_id);
  IF epoch_now IS DISTINCT FROM a.dependency_epoch
   OR NOT EXISTS(SELECT 1 FROM public.controlled_change_coverage_currents c
    WHERE c.tenant_id=a.tenant_id AND c.product_id=a.product_id AND c.project_id=a.project_id
     AND c.change_id=a.change_id AND c.purpose_sha256=a.purpose_sha256 AND c.fact_id=a.id
     AND c.revision=a.revision AND c.epoch=a.epoch)
   OR NOT EXISTS(SELECT 1 FROM public.change_request_currents c
    WHERE c.tenant_id=a.tenant_id AND c.product_id=a.product_id AND c.change_id=a.change_id
     AND c.id=(a.input_snapshot->'origin_binding'->>'current_id')::uuid
     AND c.version_id=(a.input_snapshot->'origin_binding'->>'version_id')::uuid
     AND c.revision=(a.input_snapshot->'origin_binding'->>'revision')::integer)
  THEN RAISE EXCEPTION 'coverage publication needs its exact current origin/clock/target'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.artifact_versions v WHERE v.tenant_id=a.tenant_id
   AND v.product_id=a.product_id AND v.id=(a.source->>'id')::uuid
   AND v.revision=(a.source->>'revision')::integer AND v.original_id IS NULL AND v.status='active')
  THEN RAISE EXCEPTION 'coverage publication native original is no longer current'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.principals p WHERE p.tenant_id=a.tenant_id
    AND p.id=a.actor_id AND p.active AND p.kind='human')
   OR NOT EXISTS(SELECT 1 FROM public.grants g WHERE g.tenant_id=a.tenant_id
    AND g.product_id=a.product_id AND g.principal_id=a.actor_id AND g.can_write
    AND g.expires_at>clock_timestamp())
   OR clock_timestamp()>=LEAST(a.valid_until,(a.authority_snapshot->>'valid_until')::timestamptz)
  THEN RAISE EXCEPTION 'coverage publication current identity/window unavailable'; END IF;
 END IF;
 RETURN NULL;
END $function$
